namespace IQ2i\HerseBundle\Bridge\Moka\Model;

/**
 * What the email second factor of scheb needs on the user, added to the user class generated by Moka.
 *
 * @see \Scheb\TwoFactorBundle\Model\Email\TwoFactorInterface
 */
trait EmailTwoFactorTrait
{
    private bool $emailAuthEnabled = false;

    private ?string $authCode = null;

    public function isEmailAuthEnabled(): bool
    {
        return $this->emailAuthEnabled;
    }

    public function setEmailAuthEnabled(bool $emailAuthEnabled): static
    {
        $this->emailAuthEnabled = $emailAuthEnabled;

        return $this;
    }

    public function getEmailAuthRecipient(): string
    {
        return (string) $this->getEmail();
    }

    public function getEmailAuthCode(): ?string
    {
        return $this->authCode;
    }

    public function setEmailAuthCode(string $authCode): void
    {
        $this->authCode = $authCode;
    }
}
